"""
Test Suite for CatchForecast AI - PIPP Ingestion and MSY Bioeconomic Models
Verifies data provenance, schema integrity, and scientific consistency.
"""

import os
import pytest
import pandas as pd
import json

BASE_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
FISHERIES_DIR = os.path.join(BASE_DIR, "data", "raw", "fisheries")

def test_fisheries_data_files_exist():
    """Verify that all raw fisheries files were successfully generated by the ingestion pipeline."""
    expected_files = [
        "ppn_karangantu_pendaratan_bulanan.csv",
        "ppn_karangantu_pendaratan_mingguan.csv",
        "ppn_karangantu_pendaratan_harian.csv",
        "ppn_karangantu_produksi_bulanan_2026.csv",
        "ppn_karangantu_operasional_kapal.csv",
        "target_species_landings.csv",
        "raw_pipp_dump.json",
        "target_species_cpue_msy_summary.csv"
    ]
    for fname in expected_files:
        fpath = os.path.join(FISHERIES_DIR, fname)
        assert os.path.exists(fpath), f"File {fname} does not exist in {FISHERIES_DIR}"
        assert os.path.getsize(fpath) > 0, f"File {fname} is empty"

def test_target_species_integrity():
    """Verify that all 3 target species are present with correct taxonomy and positive volume."""
    fpath = os.path.join(FISHERIES_DIR, "target_species_landings.csv")
    df = pd.read_csv(fpath)
    
    assert len(df) >= 3, "Target species observations must contain at least 3 records"
    
    required_species = {
        "Rastrelliger brachysoma",
        "Selaroides leptolepis",
        "Upeneus sulphureus"
    }
    
    found_species = set(df["scientific_name"].unique())
    assert required_species.issubset(found_species), f"Missing target species: {required_species - found_species}"
    
    # Check volume and price validity
    assert (df["volume_kg"] > 0).all(), "All volumes must be strictly positive"
    assert (df["harga_rata_rata_idr"] > 0).all(), "All prices must be strictly positive"

def test_monthly_production_profile():
    """Verify the 2026 monthly production curve profile."""
    fpath = os.path.join(FISHERIES_DIR, "ppn_karangantu_produksi_bulanan_2026.csv")
    df = pd.read_csv(fpath)
    
    assert len(df) == 12, "Must contain 12 months"
    # August should be the peak landing month (~420,859 kg)
    peak_row = df.loc[df["volume_kg"].idxmax()]
    assert peak_row["bulan"] == "Agu", f"Expected peak in August, got {peak_row['bulan']}"
    assert peak_row["volume_kg"] > 400000, "August volume should exceed 400 tons"

def test_cpue_and_msy_bounds():
    """Verify that bioeconomic models compute realistic parameters."""
    fpath = os.path.join(FISHERIES_DIR, "target_species_cpue_msy_summary.csv")
    df = pd.read_csv(fpath)
    
    assert len(df) == 3, "Must contain CPUE and MSY estimates for all 3 species"
    
    for _, row in df.iterrows():
        assert row["monthly_cpue_kg_per_trip"] > 0, f"CPUE must be positive for {row['scientific_name']}"
        assert row["schaefer_msy_kg_year"] > 0, f"Schaefer MSY must be positive for {row['scientific_name']}"
        assert row["fox_msy_kg_year"] > 0, f"Fox MSY must be positive for {row['scientific_name']}"
        assert row["schaefer_e_opt_trips"] > 0, f"Optimal effort must be positive for {row['scientific_name']}"

if __name__ == "__main__":
    pytest.main(["-v", __file__])
